package com.bank.rules.engine;

import com.bank.rules.model.Transaction;
import java.math.BigDecimal;
import java.util.*;
import java.util.function.*;
import java.util.logging.*;

public class RuleEngine {
    private static final Logger log = Logger.getLogger(RuleEngine.class.getName());

    // Apply a predicate (a lambda) to each transaction and log matches.
    public List<Transaction> filter(List<Transaction> txns, Predicate<Transaction> rule) {
        var result = new ArrayList<Transaction>();
        for (Transaction t : txns) {
            if (rule.test(t)) result.add(t);   // JIT can inline through this call site
        }
        return result;
    }

    // Build a CAPTURING predicate from a runtime threshold. The lambda closes over
    // 'threshold', so LambdaMetafactory must create an instance holding that value.
    public Predicate<Transaction> highValueRule(BigDecimal threshold) {
        return t -> t.amount().compareTo(threshold) > 0;   // captures 'threshold'
    }

    // A NON-CAPTURING predicate: closes over nothing → metafactory returns a singleton,
    // reused for every evaluation of this invokedynamic site (no per-use allocation).
    public static final Predicate<Transaction> IS_CREDIT = t -> t.amount().signum() > 0;
}
