package com.bank.rules;

import com.bank.rules.engine.RuleEngine;
import com.bank.rules.model.Transaction;
import java.math.BigDecimal;
import java.util.*;
import java.util.function.Predicate;
import java.util.logging.*;

public class LambdaDemo {
    private static final Logger log = Logger.getLogger(LambdaDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        var engine = new RuleEngine();
        List<Transaction> txns = List.of(
                new Transaction("SAV2001", new BigDecimal("1200000.00")),  // Rajesh, high
                new Transaction("CUR3001", new BigDecimal("8000.00")),     // Priya, low
                new Transaction("SAV2001", new BigDecimal("500000.00"))    // Rajesh, mid
        );

        // CAPTURING lambda: threshold decided at runtime (Rs.10,00,000).
        Predicate<Transaction> highValue = engine.highValueRule(new BigDecimal("1000000.00"));
        List<Transaction> high = engine.filter(txns, highValue);
        log.info(() -> "High-value transactions (> Rs.10,00,000): " + high.size());
        high.forEach(t -> log.info(() -> "  HIGH " + t.accountId() + " Rs." + t.amount()));

        // NON-CAPTURING lambda reuse: the SAME expression yields the SAME object.
        Predicate<Transaction> a = RuleEngine.IS_CREDIT;
        Predicate<Transaction> b = RuleEngine.IS_CREDIT;
        log.info(() -> "Non-capturing lambda reused (same instance)? " + (a == b));  // true

        List<Transaction> credits = engine.filter(txns, RuleEngine.IS_CREDIT);
        log.info(() -> "Credit transactions: " + credits.size());
        log.info("Lambdas compiled to synthetic methods + invokedynamic (LambdaMetafactory)");
    }
}
